head.script:

	scwin.onpageload = function() {
		var index=0;
//		generator1.getChild(1, "group1");

		generator1.insertChild(index);

	};

	scwin.onpageunload = function() {

	};


	scwin.searchbox1_onviewchange = function(info) {
		console.log("scwin.searchbox1_onviewchange");
		console.log(info);
	};

	scwin.searchbox2_onviewchange = function(info) {
		console.log("scwin.searchbox2_onviewchange");
		console.log(info);
	};


	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		WebSquare.wUnit.getJq('#generator1_0_searchbox1___input').simulate('key-sequence', {
			sequence: '12345'
		});
	}
	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('generator1_0_searchbox1___input').getAttribute('maxlength') == '3';
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('generator1_0_searchbox1___input').click()");
		//WebSquare.wUnit.addCommand("pause", "500");
		//WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		//WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
